--
-- Table structure for table `waste_container`
--

CREATE TABLE `waste_container` (
  `bin_id` int(11) NOT NULL,
  `status_id` int(11) NOT NULL,
  `bin_number` varchar(100) NOT NULL,
  `bin_type` varchar(100) NOT NULL,
  `capacity` decimal(10,2) NOT NULL,
  `current_fill_level` decimal(10,2) NOT NULL,
  `location` varchar(255) NOT NULL,
  `last_collection_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

